-- Tests authored before migration. Explicit outer transaction leaves no fixtures.
begin;
create temporary table wp18_ids(label text primary key,id uuid);
create temporary table wp18_saved(label text primary key,data jsonb);
create temporary table wp18_results(label text,passed boolean);
grant select,insert,update on wp18_ids,wp18_saved,wp18_results to authenticated;
create function pg_temp.wp18_check(label text,passed boolean) returns void language sql security invoker as $$insert into pg_temp.wp18_results values(label,coalesce(passed,false))$$;
create function pg_temp.wp18_error(label text,query text,expected text) returns void language plpgsql security invoker as $$declare caught text;begin begin execute query;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.wp18_check(label,caught=expected);end;$$;
create function pg_temp.wp18_id(label text) returns uuid language sql security invoker as $$select id from pg_temp.wp18_ids where wp18_ids.label=$1$$;
create function pg_temp.wp18_version() returns text language sql security invoker as $$select state_version from public.weddings where id=pg_temp.wp18_id('a')$$;
create function pg_temp.wp18_active() returns jsonb language sql security invoker as $$select jsonb_build_object('wedding',to_jsonb(w),'ceremonies',(select jsonb_agg(to_jsonb(c) order by c.id) from public.ceremonies c where c.wedding_id=w.id),'tasks',(select jsonb_agg(to_jsonb(t) order by t.id) from public.tasks t where t.wedding_id=w.id),'costs',(select jsonb_agg(to_jsonb(i) order by i.id) from public.cost_items i where i.wedding_id=w.id),'cash',(select jsonb_agg(to_jsonb(e) order by e.id) from public.cash_entries e where e.wedding_id=w.id)) from public.weddings w where w.id=pg_temp.wp18_id('a')$$;
insert into auth.users(id,email) values('18000000-0000-4000-8000-000000000001','wp18-rollback-a@example.invalid'),('18000000-0000-4000-8000-000000000002','wp18-rollback-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"18000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp18_ids values('a',public.create_wedding('WP18 SQL synthetic','Test city'));
select public.save_draft_setup(pg_temp.wp18_id('a'),pg_temp.wp18_version(),'WP18 SQL synthetic','Test city',null,true,null,'[{"title":"Reception","guest_count":300}]');
insert into wp18_ids select 'ceremony',id from public.ceremonies where wedding_id=pg_temp.wp18_id('a');
reset role;
update wedding_private.ceremonies set venue_capacity=320 where id=pg_temp.wp18_id('ceremony') and wedding_id=pg_temp.wp18_id('a');
set local role authenticated;
select public.generate_draft(pg_temp.wp18_id('a'),pg_temp.wp18_version());
select public.activate_plan(pg_temp.wp18_id('a'),pg_temp.wp18_version(),true);
select public.finance_cost(pg_temp.wp18_id('a'),null,pg_temp.wp18_version(),'create',jsonb_build_object('title','Return gifts','ceremony_id',pg_temp.wp18_id('ceremony'),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise','15000'),false,null);
select public.finance_cost(pg_temp.wp18_id('a'),null,pg_temp.wp18_version(),'create',jsonb_build_object('title','Caterer','ceremony_id',pg_temp.wp18_id('ceremony'),'pricing_basis','FIXED','fixed_estimate_paise','20000000','per_guest_rate_paise',null),false,null);
insert into wp18_ids select 'caterer',id from public.cost_items where title='Caterer' and wedding_id=pg_temp.wp18_id('a');
select public.finance_cost(pg_temp.wp18_id('a'),pg_temp.wp18_id('caterer'),pg_temp.wp18_version(),'state','{"state":"COMMITTED","amount_paise":"20000000"}',true,null);
select public.finance_cash(pg_temp.wp18_id('a'),pg_temp.wp18_id('caterer'),null,pg_temp.wp18_version(),'post','{"kind":"PAYMENT","amount_paise":"5000000","occurred_on":"2026-10-27","note":null,"intent_key":"wp18-prior-payment"}',false,null);
select public.finance_cost(pg_temp.wp18_id('a'),null,pg_temp.wp18_version(),'create',jsonb_build_object('title','Unknown rate','ceremony_id',pg_temp.wp18_id('ceremony'),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise',null),false,null);
select public.finance_cost(pg_temp.wp18_id('a'),null,pg_temp.wp18_version(),'create',jsonb_build_object('title','Fixed decoration','ceremony_id',pg_temp.wp18_id('ceremony'),'pricing_basis','FIXED','fixed_estimate_paise','100000','per_guest_rate_paise',null),false,null);
select public.update_task(pg_temp.wp18_id('a'),null,pg_temp.wp18_version(),'add',jsonb_build_object('title','WP18 completed ceremony task','ceremony_id',pg_temp.wp18_id('ceremony'),'due_date','2026-10-01'),false,false);
insert into wp18_ids select 'completed',id from public.tasks where wedding_id=pg_temp.wp18_id('a') and title='WP18 completed ceremony task';
select public.update_task(pg_temp.wp18_id('a'),pg_temp.wp18_id('completed'),pg_temp.wp18_version(),'status','{"status":"COMPLETED"}',false,false);
-- Approval assertions authored before implementation.
insert into wp18_saved values('before',pg_temp.wp18_active());
insert into wp18_saved values('rejected',public.adapt_propose(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version(),350,null));
insert into wp18_ids select 'rejected',(data->>'id')::uuid from wp18_saved where label='rejected';
select public.adapt_reject(pg_temp.wp18_id('a'),pg_temp.wp18_id('rejected'));
select pg_temp.wp18_error('rejected proposal cannot apply',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('rejected'))$$,'PT409');
select pg_temp.wp18_check('rejection/failed approval preserve active plan',pg_temp.wp18_active()=(select data from wp18_saved where label='before'));
insert into wp18_saved values('stale',public.adapt_propose(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version(),350,null));
insert into wp18_ids select 'stale',(data->>'id')::uuid from wp18_saved where label='stale';
select public.finance_cost(pg_temp.wp18_id('a'),pg_temp.wp18_id('caterer'),pg_temp.wp18_version(),'expected_refund','{"expected_refund_paise":"0"}',false,null);
insert into wp18_saved values('after-mutation',pg_temp.wp18_active());
select pg_temp.wp18_error('changed relevant version refuses stale preview',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('stale'))$$,'PT409');
select pg_temp.wp18_check('stale leaves active state unchanged',pg_temp.wp18_active()=(select data from wp18_saved where label='after-mutation'));
reset role;
insert into wedding_private.change_proposals(wedding_id,ceremony_id,base_wedding_version,old_guest_count,new_guest_count,preview_snapshot) values(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version()::bigint,300,350,'{}');
insert into wp18_ids select 'malformed',id from wedding_private.change_proposals where wedding_id=pg_temp.wp18_id('a') and preview_snapshot='{}';
set local role authenticated;
select pg_temp.wp18_error('malformed snapshot refused',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('malformed'))$$,'PT409');
select pg_temp.wp18_check('malformed leaves plan unchanged',pg_temp.wp18_active()=(select data from wp18_saved where label='after-mutation'));
insert into wp18_saved values('pending',public.adapt_propose(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version(),350,null));
insert into wp18_ids select 'pending',(data->>'id')::uuid from wp18_saved where label='pending';
-- Trigger is scoped to synthetic actor and rolled back. No client failure flag/bypass.
reset role;
create function pg_temp.wp18_fail_audit() returns trigger language plpgsql set search_path='' as $$begin if new.actor_user_id='18000000-0000-4000-8000-000000000001' and new.action='GUEST_COUNT_CHANGE_APPLIED' then raise exception using errcode='P0001',message='WP18 simulated audit failure';end if;return new;end;$$;
create trigger wp18_simulated_failure before insert on wedding_private.audit_events for each row execute function pg_temp.wp18_fail_audit();
set local role authenticated;
select pg_temp.wp18_error('simulated audit failure aborts approval',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending'))$$,'P0001');
select pg_temp.wp18_check('ceremony/version/cost/cash/tasks rolled back',pg_temp.wp18_active()=(select data from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('failed proposal still PENDING',(select status from public.change_proposals where id=pg_temp.wp18_id('pending'))='PENDING');
select pg_temp.wp18_check('failed approval audit absent',not exists(select 1 from public.audit_events where wedding_id=pg_temp.wp18_id('a') and action='GUEST_COUNT_CHANGE_APPLIED'));
reset role;
drop trigger wp18_simulated_failure on wedding_private.audit_events;
set local role authenticated;
insert into wp18_saved values('applied',public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending')));
select pg_temp.wp18_check('approval returns APPLIED',(select data->>'status' from wp18_saved where label='applied')='APPLIED');
select pg_temp.wp18_check('guest count now350',(select guest_count from public.ceremonies where id=pg_temp.wp18_id('ceremony'))=350);
select pg_temp.wp18_check('one trigger version increment',pg_temp.wp18_version()::bigint=(select (data->'wedding'->>'state_version')::bigint+1 from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('all task records unchanged',(pg_temp.wp18_active()->'tasks')=(select data->'tasks' from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('all cost commitments and terms unchanged',(pg_temp.wp18_active()->'costs')=(select data->'costs' from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('all payment/refund history unchanged',(pg_temp.wp18_active()->'cash')=(select data->'cash' from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('other wedding fields preserved',((pg_temp.wp18_active()->'wedding')-'state_version'-'updated_at')=(select (data->'wedding')-'state_version'-'updated_at' from wp18_saved where label='after-mutation'));
select pg_temp.wp18_check('ceremony configuration preserved',(select jsonb_agg(value-'guest_count'-'updated_at' order by value->>'id') from jsonb_array_elements(pg_temp.wp18_active()->'ceremonies'))=(select jsonb_agg(value-'guest_count'-'updated_at' order by value->>'id') from jsonb_array_elements((select data->'ceremonies' from wp18_saved where label='after-mutation'))));
select pg_temp.wp18_check('forecast recomputes45000to52500',exists(select 1 from public.cost_items i join public.ceremonies c on c.id=i.ceremony_id where i.wedding_id=pg_temp.wp18_id('a') and i.title='Return gifts' and i.per_guest_rate_paise::numeric*300=4500000 and i.per_guest_rate_paise::numeric*c.guest_count=5250000));
select pg_temp.wp18_check('prior50000 payment preserved',(select amount_paise from public.cash_entries where intent_key='wp18-prior-payment')='5000000');
select pg_temp.wp18_check('exactly one same-owner linked audit',(select count(*) from public.audit_events where wedding_id=pg_temp.wp18_id('a') and action='GUEST_COUNT_CHANGE_APPLIED' and entity_id=pg_temp.wp18_id('pending') and actor_user_id='18000000-0000-4000-8000-000000000001')=1);
select pg_temp.wp18_check('applied metadata/version/audit consistent',exists(select 1 from public.change_proposals p join public.audit_events a on a.wedding_id=p.wedding_id and a.id=p.applied_audit_event_id where p.id=pg_temp.wp18_id('pending') and p.status='APPLIED' and p.decided_at is not null and p.applied_version=pg_temp.wp18_version() and a.entity_id=p.id));
select pg_temp.wp18_check('current impact audit exact7500 and unknown rate not zero',exists(select 1 from public.audit_events where entity_id=pg_temp.wp18_id('pending') and action='GUEST_COUNT_CHANGE_APPLIED' and before_after->>'known_estimate_delta_paise'='750000' and before_after->>'known_estimate_items'='1' and before_after->>'unknown_estimate_items'='1'));
select pg_temp.wp18_check('snapshot immutable after apply',(select preview_snapshot from public.change_proposals where id=pg_temp.wp18_id('pending'))=(select data->'preview_snapshot' from wp18_saved where label='pending'));
insert into wp18_saved values('after-apply',pg_temp.wp18_active());
insert into wp18_saved values('replay',public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending')));
select pg_temp.wp18_check('same proposal replay harmless',pg_temp.wp18_active()=(select data from wp18_saved where label='after-apply'));
select pg_temp.wp18_check('replay returns same applied version and audit',(select data->>'applied_version' from wp18_saved where label='replay')=(select data->>'applied_version' from wp18_saved where label='applied') and (select data->>'applied_audit_event_id' from wp18_saved where label='replay')=(select data->>'applied_audit_event_id' from wp18_saved where label='applied'));
select pg_temp.wp18_check('replay no extra audit',(select count(*) from public.audit_events where wedding_id=pg_temp.wp18_id('a') and action='GUEST_COUNT_CHANGE_APPLIED')=1);
insert into wp18_saved values('tab1',public.adapt_propose(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version(),360,null)),('tab2',public.adapt_propose(pg_temp.wp18_id('a'),pg_temp.wp18_id('ceremony'),pg_temp.wp18_version(),370,null));
insert into wp18_ids select label,(data->>'id')::uuid from wp18_saved where label in('tab1','tab2');
select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('tab1'));
select pg_temp.wp18_error('competing pending tab is stale after first winner',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('tab2'))$$,'PT409');
select pg_temp.wp18_check('stale tab never changes count to370',(select guest_count from public.ceremonies where id=pg_temp.wp18_id('ceremony'))=360);
select pg_temp.wp18_check('old APPLIED replay does not overwrite later count',(public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending'))->>'current_guest_count')='360' and (select guest_count from public.ceremonies where id=pg_temp.wp18_id('ceremony'))=360);
select pg_temp.wp18_error('authenticated direct count denied',$$update public.ceremonies set guest_count=500 where id=pg_temp.wp18_id('ceremony')$$,'42501');
select pg_temp.wp18_error('authenticated private-table count denied',$$update wedding_private.ceremonies set guest_count=500 where id=pg_temp.wp18_id('ceremony')$$,'42501');
select pg_temp.wp18_error('arbitrary proposal edits denied',$$update public.change_proposals set status='APPLIED' where id=pg_temp.wp18_id('tab2')$$,'42501');
select pg_temp.wp18_error('arbitrary audit edits denied',$$update public.audit_events set action='FORGED' where wedding_id=pg_temp.wp18_id('a')$$,'42501');
select pg_temp.wp18_check('anon cannot execute approval',not has_function_privilege('anon','public.adapt_approve(uuid,uuid)','execute'));
select pg_temp.wp18_check('no client role membership',not pg_has_role('authenticated','wedding_guest_approver','member'));
select pg_temp.wp18_check('approver cannot edit costs/cash/tasks',not has_table_privilege('wedding_guest_approver','wedding_private.cost_items','UPDATE') and not has_table_privilege('wedding_guest_approver','wedding_private.cash_entries','UPDATE') and not has_table_privilege('wedding_guest_approver','wedding_private.tasks','UPDATE'));
select pg_temp.wp18_check('safe definer role and search path',(select p.prosecdef and r.rolname='wedding_guest_approver' and not r.rolcanlogin and not r.rolbypassrls and p.proconfig @> array['search_path=""'] from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='public.adapt_approve(uuid,uuid)'::regprocedure));
select set_config('request.jwt.claims','{"sub":"18000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into wp18_ids values('b',public.create_wedding('WP18 B synthetic','Test city'));
select pg_temp.wp18_error('B cannot approve A',$$select public.adapt_approve(pg_temp.wp18_id('a'),pg_temp.wp18_id('tab2'))$$,'42501');
select pg_temp.wp18_error('forged B wedding with A proposal denied',$$select public.adapt_approve(pg_temp.wp18_id('b'),pg_temp.wp18_id('tab2'))$$,'42501');
select pg_temp.wp18_check('B cannot read A authoritative outcome',public.adapt_outcome(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending')) is null);
select set_config('request.jwt.claims','{"sub":"18000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.wp18_check('authoritative outcome reflects later count',(public.adapt_outcome(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending'))->>'status')='APPLIED' and (public.adapt_outcome(pg_temp.wp18_id('a'),pg_temp.wp18_id('pending'))->>'current_guest_count')='360');
reset role;
select jsonb_build_object('checks',jsonb_agg(jsonb_build_object('name',label,'passed',passed)),'total',count(*),'passed',count(*) filter(where passed),'failed',count(*) filter(where not passed)) as wp18_result from wp18_results;
rollback;
